async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let fragments = [];
  let line = 1;
  let count = 0;

  async function processLine(text) {
    const currentLine = line++;
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${currentLine}`);
      error.code = "BAD_LINE";
      error.line = currentLine;
      throw error;
    }

    count++;
    return (await deliver(value, currentLine)) !== false;
  }

  try {
    for (;;) {
      const chunk = await input.read();
      const eof = chunk === null;
      const text = eof
        ? decoder.decode()
        : decoder.decode(chunk, { stream: true });

      let start = 0;
      let end;

      while ((end = text.indexOf("\n", start)) !== -1) {
        fragments.push(text.slice(start, end));
        const completeLine = fragments.join("");
        fragments = [];

        if (!(await processLine(completeLine))) return count;
        start = end + 1;
      }

      if (start < text.length) fragments.push(text.slice(start));

      if (eof) {
        if (fragments.length > 0) {
          await processLine(fragments.join(""));
        }
        return count;
      }
    }
  } finally {
    await input.close();
  }
}
